#!/usr/bin/env bash
# tests/check-html-entities-sync.sh -- markdown-library-plan U2: the HTML entity
# table exists twice, generated by tools/gen-html-entities.py: the file-scope C
# block of stdlib/markdown/entities.tur (the compiled back end) and
# src/turi/html_entities.inc (the interpreter's natives).  They must be the
# same text, or the two back ends answer differently.  This checks the two
# copies against each other, not against the generator, so it does not depend
# on the local Python's copy of the entity list.
set -uo pipefail
cd "$(dirname "$0")/.."
if ! command -v python3 >/dev/null 2>&1; then
    echo "SKIP check-html-entities-sync: python3 not found"
    exit 0
fi
python3 - <<'PY'
import sys
tur = open("stdlib/markdown/entities.tur", encoding="ascii").read()
inc = open("src/turi/html_entities.inc", encoding="ascii").read()
start = tur.index("```c\n") + 5
end = tur.index("```\n", start)
if tur[start:end] != inc:
    print("FAIL check-html-entities-sync: stdlib/markdown/entities.tur's C block "
          "and src/turi/html_entities.inc differ -- regenerate both with "
          "python3 tools/gen-html-entities.py")
    sys.exit(1)
print("PASS check-html-entities-sync (%d bytes of C, identical)" % len(inc))
PY
